import {
  APP_USER_SCOPES,
  SERVICE_SCOPES,
  internalAudience,
  oauthClient,
  type AppKey,
} from "@workspace/contracts"
import { appOrigin } from "@workspace/contracts/server"

/**
 * First-party OAuth client manifest.
 *
 * Client IDs are stable (`asynchrone-<app>`); secrets are generated by the
 * authorization server and written to the deployment environment by
 * `scripts/provision-oauth-clients.ts`. Never commit them.
 */
export interface OAuthClientManifestEntry {
  key: AppKey
  clientId: string
  clientName: string
  clientIdEnv: string
  clientSecretEnv: string
  redirectUris: string[]
  postLogoutRedirectUris: string[]
  backchannelLogoutUri: string | null
  backchannelLogoutSessionRequired: boolean
  grantTypes: string[]
  scopes: string[]
  clientCredentialsScopes: string[]
  resources: string[]
  skipConsent: boolean
  enableEndSession: boolean
  tokenEndpointAuthMethod: "client_secret_basic"
  applicationType: "web"
}

const USER_GRANTS = [
  "authorization_code",
  "refresh_token",
  "client_credentials",
]
const SERVICE_GRANTS = ["client_credentials"]

const DOMAIN_KEYS = [
  "projects",
  "calendars",
  "files",
  "messages",
  "clients",
  "employees",
] as const

function clientId(key: AppKey): string {
  return `asynchrone-${key}`
}

function envNames(key: AppKey) {
  const client = oauthClient(key)
  if (!client) throw new Error(`No OAuth client env for ${key}`)
  return client
}

function userClient(
  key: (typeof DOMAIN_KEYS)[number]
): OAuthClientManifestEntry {
  const origin = appOrigin(key)
  const client = envNames(key)
  return {
    key,
    clientId: clientId(key),
    clientName: `Asynchrone Space ${key}`,
    clientIdEnv: client.clientIdEnv,
    clientSecretEnv: client.clientSecretEnv,
    redirectUris: [`${origin}/api/auth/callback`],
    postLogoutRedirectUris: [origin],
    backchannelLogoutUri: `${origin}/api/auth/backchannel-logout`,
    backchannelLogoutSessionRequired: true,
    grantTypes: USER_GRANTS,
    scopes: [...APP_USER_SCOPES],
    clientCredentialsScopes: [
      SERVICE_SCOPES.identityRead,
      SERVICE_SCOPES.notificationsWrite,
    ],
    resources: [internalAudience(key), internalAudience("copilot")],
    skipConsent: true,
    enableEndSession: true,
    tokenEndpointAuthMethod: "client_secret_basic",
    applicationType: "web",
  }
}

function serviceClient(
  key: "copilot" | "control-tower"
): OAuthClientManifestEntry {
  const client = envNames(key)
  const isCopilot = key === "copilot"
  return {
    key,
    clientId: clientId(key),
    clientName: `Asynchrone Space ${key} service`,
    clientIdEnv: client.clientIdEnv,
    clientSecretEnv: client.clientSecretEnv,
    redirectUris: [],
    postLogoutRedirectUris: [],
    backchannelLogoutUri: null,
    backchannelLogoutSessionRequired: false,
    grantTypes: SERVICE_GRANTS,
    scopes: [],
    clientCredentialsScopes: isCopilot
      ? [
          SERVICE_SCOPES.domainRead,
          SERVICE_SCOPES.domainWrite,
          SERVICE_SCOPES.auditRead,
          SERVICE_SCOPES.searchRead,
          SERVICE_SCOPES.exportRead,
          SERVICE_SCOPES.deleteWrite,
        ]
      : [SERVICE_SCOPES.identityRead, SERVICE_SCOPES.identityAdmin],
    resources: isCopilot
      ? DOMAIN_KEYS.map((domain) => internalAudience(domain))
      : [internalAudience("copilot")],
    skipConsent: true,
    enableEndSession: false,
    tokenEndpointAuthMethod: "client_secret_basic",
    applicationType: "web",
  }
}

export function buildOAuthClientManifest(): OAuthClientManifestEntry[] {
  return [
    ...DOMAIN_KEYS.map(userClient),
    serviceClient("copilot"),
    serviceClient("control-tower"),
  ]
}

export function manifestClientKeys(): string[] {
  return buildOAuthClientManifest().map((entry) => entry.clientId)
}
